<?php

declare(strict_types=1);

/**
 * F1-245: prove the gallery is generated by the real INERT structured-copy
 * adapter, private content-addressed draft and human-review gate. The actor
 * labels here are fiction; they cannot authenticate actual Portal clients.
 */
if (PHP_SAPI!=='cli' || getenv('GITHUB_ACTIONS')!=='true' ||
    getenv('APP_ENV')!=='testing' ||
    getenv('SITES_F238_DEMO_ARTIFACT')!=='1') {
    throw new RuntimeException('F1-245 is explicitly gated to test runners.');
}
require __DIR__.'/../apps/sites/vendor/autoload.php';

use Imagine\Sites\Production\StructuredCopyCandidate;
use Imagine\Sites\Production\SyntheticStructuredDraftAssembly as Assembly;
use Imagine\Sites\Production\SyntheticReleaseBundle;
use Imagine\Sites\Production\SyntheticProductionWorkflow as Workflow;

function affirm245(bool $ok,string $message):void {
    global $checks;
    if(!$ok)throw new RuntimeException('F1-245: '.$message);
    ++$checks;
}
function denied245(callable $operation):bool {
    try{$operation();}
    catch(DomainException|InvalidArgumentException){return true;}
    return false;
}
$copy=json_decode(
    (string)file_get_contents(__DIR__.'/../fixtures/sites/f1-170-process-copy.synthetic.json'),
    true,16,JSON_THROW_ON_ERROR
);
$manifest=json_decode(
    (string)file_get_contents(__DIR__.'/../apps/sites/storage/app/private/f238-demo-previews/manifest.json'),
    true,16,JSON_THROW_ON_ERROR
);
affirm245($manifest['generationPath']==='synthetic_structured_copy_to_internal_review'
    && $manifest['internalReviewRequired']===true
    && $manifest['portalAuthorityRequired']===true
    && $manifest['publishable']===false
    && $manifest['approvedForClient']===false
    && $manifest['draftState']===Workflow::INTERNAL_REVIEW,
    'gallery manifest never forges a publish/approval grant');
$checks=1;
foreach(['onepage','landing_page'] as $product) {
    foreach(['classic','modern','warm'] as $style) {
        $candidate=StructuredCopyCandidate::assemble(
            $product,'Aurora Exemplo',$copy
        );
        affirm245($candidate->productCode===$product &&
            $candidate->brand==='Aurora Exemplo' &&
            $candidate->processSteps===$copy['processSteps'] &&
            $candidate->highlights===$copy['highlights'] &&
            $candidate->faq===$copy['faq'],
            'v4 copies never control official product or brand');
        $draft=Assembly::build(
            $product,'Aurora Exemplo',$style,$copy,
            'tenant-f245-demo','site-f245-demo',
            'workflow-f245-'.$product.'-'.$style,
            'release-f245-'.$product.'-'.$style,
            ['highlights','process','faq'],$product==='onepage',
            null,true,
            $copy['headline'].' | Aurora Exemplo',
            $copy['description']
        );
        $review=$draft->reviewSummary();
        $file=$product.'-'.$style.'.html';
        affirm245($draft->workflow->state===Workflow::INTERNAL_REVIEW &&
            $draft->workflow->revision===2 &&
            $review['internalReviewRequired']===true &&
            $review['portalAuthorityRequired']===true &&
            $review['officialClientAcceptance']===false &&
            $review['publishable']===false,
            'AI-like output is only a private draft under internal review');
        affirm245($draft->structuralReport->passedStructuralChecks &&
            SyntheticReleaseBundle::verifyFiles($draft->bundle->files,$draft->manifest) &&
            hash_equals($manifest['files'][$file]['sha256'],$draft->artifact->digest),
            'structured copy → exact gallery HTML → bundle digest parity');
        affirm245($manifest['files'][$file]['draftState']===Workflow::INTERNAL_REVIEW &&
            $manifest['files'][$file]['officialClientAcceptance']===false &&
            $manifest['files'][$file]['publishable']===false,
            'onefile review flags remain demo-only');
        affirm245(denied245(static fn()=>$draft->workflow->advance(
            'agent','approve_internal',2,$draft->artifact->digest
        )) && denied245(static fn()=>$draft->workflow->portalReviewCandidate(
            $draft->manifest->releaseRef,$draft->artifact->digest,2
        )),
            'agent may not approve the draft or forge Portal review');
        $internal=$draft->workflow->advance(
            'imagine_reviewer','approve_internal',2,$draft->artifact->digest
        );
        $candidatePortal=$internal->portalReviewCandidate(
            $draft->manifest->releaseRef,$draft->artifact->digest,3
        );
        affirm245($internal->state===Workflow::AWAITING_PORTAL_ACCEPTANCE &&
            $candidatePortal['officialClientAcceptance']===false &&
            $candidatePortal['publishable']===false &&
            $candidatePortal['portalAuthorityRequired']===true,
            'even synthetic internal reviewer cannot grant real client acceptance');
        affirm245(denied245(static fn()=>$draft->workflow->advance(
            'imagine_reviewer','approve_internal',1,$draft->artifact->digest
        )) && denied245(static fn()=>$draft->workflow->advance(
            'imagine_reviewer','approve_internal',2,str_repeat('0',64)
        )),
            'stale internal review or wrong release digest denied');
    }
}
foreach([
    ['publishable',true],
    ['officialClientAcceptance',true],
    ['tenantRef','tenant-outside'],
    ['productCode','landing_page'],
    ['brand','unexpected actor'],
    ['stylePreset','custom-css'],
] as [$key,$value]) {
    $bad=$copy;
    $bad[$key]=$value;
    affirm245(denied245(static fn()=>StructuredCopyCandidate::assemble(
        'onepage','Aurora Exemplo',$bad
    )),'v4 provider cannot inject authority field '.$key);
}
$bad=$copy;
$bad['processSteps'][0]['title']='<script>alert(1)</script>';
affirm245(denied245(static fn()=>Assembly::build(
    'onepage','Aurora Exemplo','classic',$bad,
    'tenant-f245-demo','site-f245-demo','workflow-test','release-test'
)),'active HTML from untrusted copy is rejected before draft build');
$bad=$copy;
$bad['faq'][0]['answer']='https://remote.example.invalid/path';
affirm245(denied245(static fn()=>StructuredCopyCandidate::assemble(
    'onepage','Aurora Exemplo',$bad
)),'remote destination from untrusted copy rejected');

echo "$checks F1-245 copy v4 -> draft -> QA -> private package -> manual review gates passed.\n";
